SELECT m.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary m JOIN activities act ON m.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_records cr ON act.record_id = cr.record_id JOIN docs d ON cr.doc_id = d.doc_id JOIN compound_structures cs ON m.molregno = cs.molregno WHERE td.chembl_id = 'CHEMBL325' AND act.standard_type = 'IC50' AND act.standard_units = 'nM' AND act.standard_relation = '=' ORDER BY m.chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id, td.pref_name, td.organism
